"""数据探索路由 — SQL 查询 / 全市场扫描 / 横截面分析 / 异常检测

数据来源均为本地 Parquet 行情缓存（data/cache/{period}/{code}.parquet），
无缓存数据时返回明确的空结果与提示，不伪造数据。
"""

import math
import re
import time
from pathlib import Path

import numpy as np
import pandas as pd
from fastapi import APIRouter
from pydantic import BaseModel

from backend.config import settings
from backend.database import get_db
from backend.services import market_data
from backend.services.duckdb_service import DuckDBService

router = APIRouter()

duckdb_service = DuckDBService()

_SQL_FORBIDDEN = re.compile(
    r"\b(insert|update|delete|drop|create|alter|attach|detach|"
    r"export|copy|import|install|load|pragma|call)\b",
    re.IGNORECASE,
)


def _cache_files(period: str = "1d") -> list[Path]:
    d = settings.cache_dir / period
    if not d.exists():
        return []
    return sorted(d.glob("*.parquet"))


def _file_code(path: Path) -> str:
    """000001_SZ.parquet → 000001.SZ"""
    return path.stem.replace("_", ".")


def _load_stock(path: Path) -> pd.DataFrame | None:
    try:
        df = pd.read_parquet(path)
        df.index = pd.to_datetime(df.index)
        return df

    except Exception:
        return None


def _clean_value(val):
    if isinstance(val, float) and (math.isnan(val) or math.isinf(val)):
        return None
    if isinstance(val, (pd.Timestamp,)):
        return str(val)
    if isinstance(val, (np.integer,)):
        return int(val)
    if isinstance(val, (np.floating,)):
        return float(val)
    return val


# ── SQL 查询 ─────────────────────────────────────────────────


class SQLQueryRequest(BaseModel):
    sql: str


class SaveSQLRequest(BaseModel):
    name: str
    sql: str


async def _record_sql(sql: str, name: str = "") -> None:
    """记录 SQL 历史（最近 200 条以内按 last_used_at 去重覆盖）"""
    cleaned = sql.strip().rstrip(";").strip()
    if not cleaned:
        return
    now = int(time.time())
    db = await get_db()
    try:
        cursor = await db.execute(
            "SELECT id, last_used_at FROM research_sql_queries WHERE sql = ?",
            (cleaned,),
        )
        row = await cursor.fetchone()
        if row:
            await db.execute(
                "UPDATE research_sql_queries SET last_used_at = ? WHERE id = ?",
                (now, row["id"]),
            )
        else:
            await db.execute(
                "INSERT INTO research_sql_queries (name, sql, created_at, last_used_at) "
                "VALUES (?, ?, ?, ?)",
                (name or "未命名查询", cleaned, now, now),
            )
        await db.commit()
    finally:
        await db.close()


@router.post("/query")
async def sql_query(body: SQLQueryRequest):
    """DuckDB SQL 查询本地 Parquet 数据（仅允许 SELECT）"""
    sql = body.sql.strip().rstrip(";")
    if not sql:
        return {
            "columns": [],
            "data": [],
            "row_count": 0,
            "error": "SQL 为空",
            "code": "invalid_query",
        }
    if not sql.lower().lstrip("(").startswith(("select", "with", "describe", "show")):
        return {
            "columns": [],
            "data": [],
            "row_count": 0,
            "error": "仅支持 SELECT / WITH / DESCRIBE 查询",
            "code": "invalid_query",
        }
    if _SQL_FORBIDDEN.search(sql):
        return {
            "columns": [],
            "data": [],
            "row_count": 0,
            "error": "SQL 中包含不允许的写操作关键字",
            "code": "invalid_query",
        }
    result = duckdb_service.query_local(sql)
    if isinstance(result, dict) and result.get("error"):
        result.setdefault("code", "query_error")
        return result
    await _record_sql(sql)
    return result


class SQLHistoryEntry(BaseModel):
    id: int
    name: str
    sql: str
    created_at: int
    last_used_at: int | None


@router.get("/sql/queries")
async def list_sql_queries():
    """已保存/最近使用的 SQL 查询"""
    db = await get_db()
    try:
        cursor = await db.execute(
            "SELECT id, name, sql, created_at, last_used_at "
            "FROM research_sql_queries ORDER BY last_used_at DESC LIMIT 200"
        )
        rows = await cursor.fetchall()
        return {"queries": [dict(r) for r in rows]}
    finally:
        await db.close()


@router.post("/sql/queries")
async def save_sql_query(req: SaveSQLRequest):
    """保存常用 SQL（同名覆盖 sql，否则新增）"""
    name = req.name.strip()
    sql = req.sql.strip().rstrip(";").strip()
    if not name or not sql:
        return {"error": "name 与 sql 不能为空", "code": "invalid_request"}
    now = int(time.time())
    db = await get_db()
    try:
        cursor = await db.execute(
            "SELECT id FROM research_sql_queries WHERE name = ?", (name,)
        )
        row = await cursor.fetchone()
        if row:
            await db.execute(
                "UPDATE research_sql_queries SET sql = ?, last_used_at = ? WHERE id = ?",
                (sql, now, row["id"]),
            )
            query_id = row["id"]
        else:
            cursor = await db.execute(
                "INSERT INTO research_sql_queries (name, sql, created_at, last_used_at) "
                "VALUES (?, ?, ?, ?)",
                (name, sql, now, now),
            )
            query_id = cursor.lastrowid
        await db.commit()
        return {"id": query_id, "name": name, "sql": sql}
    finally:
        await db.close()


@router.delete("/sql/queries/{query_id}")
async def delete_sql_query(query_id: int):
    db = await get_db()
    try:
        await db.execute("DELETE FROM research_sql_queries WHERE id = ?", (query_id,))
        await db.commit()
        return {"deleted": query_id}
    finally:
        await db.close()


FIELD_DICTIONARY = {
    "open": "开盘价（原始价）",
    "high": "最高价（原始价）",
    "low": "最低价（原始价）",
    "close": "收盘价（原始价）",
    "volume": "成交量（股/手，以 QMT 返回单位为准）",
    "amount": "成交额（元）",
    "adjust_factor": "复权因子（后复权价/原始价；前复权=close×factor/最新factor）",
    "turnover": "换手率（需股本快照）",
}

        if mc is not None:
            aug["market_cap"] = mc
        turn = reference_data.build_turnover_panel(panels.get("volume"), close)
        if turn is not None:
            aug["turnover"] = turn
        industry_map = reference_data.load_industry_map()
    except Exception:
        logger.debug("市值/换手率/行业面板不可用，跳过注入", exc_info=True)
        mc, turn, industry_map = None, None, None
    # 基本面公告日点位：仅股票代码区间内已有快照记录的字段注入，避免 fund_xxx 无从取值
    fundamental_panels = {}
    try:
        from backend.services.fundamental import build_fundamental_panels

        fundamental_panels = build_fundamental_panels(
            list(close.columns), close.index
        ) or {}
    except Exception:
        fundamental_panels = {}
    # 构建公式求值命名空间：基础字段 + vwap/returns + 全部量化算子
    # （RANK/DELAY/DELTA/CORR/TS_RANK/DECAYLINEAR 等，大小写均可），
    # 使因子库中的 Alpha101/Alpha191 公式可直接运行。
    from backend.services.factor_operators import build_operator_namespace

    eval_ctx = build_operator_namespace(
        aug,
        industry_map=industry_map,
        fundamental={f"fund_{f}": p for f, p in fundamental_panels.items()},
    )

    try:
        if req.mode == "formula":
            if not req.formula.strip():
                raise ValueError(
                    "因子公式为空，请输入表达式，如: RANK(close / DELAY(close, 5) - 1)"
                )
            # 支持多行公式：取最后一个非空表达式作为因子值（对齐官网中间变量写法）
            formula_lines = [
                ln
                for ln in req.formula.strip().splitlines()
                if ln.strip() and not ln.strip().startswith("#")
            ]
            if len(formula_lines) > 1:
                exec_ctx = dict(eval_ctx)
                exec("\n".join(formula_lines[:-1]), {"__builtins__": {}}, exec_ctx)  # noqa: S102
                factor = eval(formula_lines[-1], {"__builtins__": {}}, exec_ctx)
            else:
                factor = eval(req.formula, {"__builtins__": {}}, eval_ctx)
        else:
            if not req.code.strip():
                raise ValueError("因子代码为空")
            exec_ctx = dict(eval_ctx)
            exec(req.code, {"__builtins__": __builtins__}, exec_ctx)  # noqa: S102
            fn = exec_ctx.get("compute_factor")
            if callable(fn):
                factor = fn(close=close, volume=panels.get("volume"))
            else:
                factor = exec_ctx.get("factor_data")
            if factor is None:
                raise ValueError("代码未定义 compute_factor 函数或 factor_data 变量")
        if isinstance(factor, pd.Series):
            factor = factor.to_frame()
        if not isinstance(factor, pd.DataFrame):
            raise TypeError(
                f"因子计算结果应为 DataFrame，得到 {type(factor).__name__}"
            )
    except HTTPException:
        raise
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        logger.error(f"因子计算失败: {e}")
        raise HTTPException(status_code=400, detail=f"因子计算失败: {e}")

    factor = factor.dropna(how="all")
    if factor.empty:
        raise HTTPException(
            status_code=400, detail="因子计算结果为空（可能回看期超过数据长度）"
        )

    # 收益面板统一为前向填充口径（与因子研究页/工作流节点一致）：
    # 停牌/缺口期间收益为 0，复牌日跳空收益计入。build_return_panel 保留完整
    # 日期索引（首日为 0），再与因子面板对齐，避免日期错位产生 NaN 截面。
    returns = market_data.build_return_panel(close)
    factor, returns = _align_factor_return(factor, returns)

    from backend.services.panel_artifact import build_panel_response

    # 全市场面板不要整表 JSON 回传：小样本内联，大样本落本地 artifact +
    # 受限预览；下游分析接口接受同一 token。
    return build_panel_response(
        {"factor_data": factor, "return_data": returns},
        inline_names=["factor_data", "return_data"],
    )


