def reference_status() -> dict:
    """参考数据现状概览，供数据管理页展示"""
    status: dict[str, dict] = {}
    for key, name, date_col in [
        ("index_constituents", _CONSTITUENTS_FILE, "date"),
        ("industry", _INDUSTRY_FILE, "date"),
        ("capital", _CAPITAL_FILE, "date"),
        ("instrument", _INSTRUMENT_FILE, "date"),
        ("universe_pools", _UNIVERSE_FILE, "date"),
    ]:
        df = _read(name)
        if df is None or df.empty:
            status[key] = {"rows": 0, "latest": None}
        else:
            status[key] = {"rows": len(df), "latest": str(df[date_col].max())}
    return status


def load_industry_map(as_of: str = "") -> dict[str, str]:
    """返回 {code: industry}，取不晚于 as_of 的最新快照（as_of 为空取最新）"""
    df = _read(_INDUSTRY_FILE)
    if df is None or df.empty:
        return {}
    if as_of:
        df = df[df["date"] <= as_of]
        if df.empty:
            # as_of 早于任何行业快照：宁可返回空（调用方退化为不按行业中性化），
            # 也不回退到 as_of 之后的「未来」行业造成前视
            return {}
    latest = df.sort_values("date").drop_duplicates("code", keep="last")
    return dict(zip(latest["code"], latest["industry"]))


def load_index_membership(index_name: str) -> pd.DataFrame | None:
    """指数成分 as-of 掩码：DataFrame(index=快照日, columns=code, bool)

    使用时按交易日 ffill 即得逐日成员；早于首次快照的日期无记录。
    """
    df = _read(_CONSTITUENTS_FILE)
    if df is None or df.empty:
        return None
    df = df[df["index_name"] == index_name]
    if df.empty:
        return None
    df = df.assign(member=True)
    mask = df.pivot_table(
        index="date", columns="code", values="member", aggfunc="any"
    ).fillna(False)
    mask.index = pd.to_datetime(mask.index)
    return mask.sort_index()


def list_snapshot_indices() -> list[str]:
    """已有成分快照的板块/指数名列表"""
    df = _read(_CONSTITUENTS_FILE)
    if df is None or df.empty:
        return []
    return sorted(df["index_name"].unique().tolist())


def build_market_cap_panel(close_panel: pd.DataFrame) -> pd.DataFrame | None:
    """流通市值面板 = 流通股本（按变动日 ffill）× 收盘价；无股本数据返回 None"""
    cap = _read(_CAPITAL_FILE)
    if cap is None or cap.empty:
        return None
    cap = cap.dropna(subset=["float_shares"])
    cap = cap[cap["float_shares"] > 0]
    if cap.empty:
        return None
    shares = cap.pivot_table(
        index="date", columns="code", values="float_shares", aggfunc="last"
    )
    shares.index = pd.to_datetime(shares.index)
    shares = shares.sort_index()
    common = close_panel.columns.intersection(shares.columns)
    if common.empty:
        return None
    # 对齐到行情日期并前向填充（股本在变动日之间保持不变）
    aligned = (
        shares[common]
        .reindex(shares.index.union(close_panel.index))
        .ffill()
        .reindex(close_panel.index)
    )
    return aligned * close_panel[common]


def build_turnover_panel(volume_panel, close_panel) -> pd.DataFrame | None:
    """换手率面板 = 成交股数 / 流通股本（按变动日 ffill）；无股本/成交数据返回 None"""
    cap = _read(_CAPITAL_FILE)
    if cap is None or cap.empty:
        return None
    if volume_panel is None or close_panel is None:
        return None
    free_shares = cap.dropna(subset=["float_shares"])
    free_shares = free_shares[free_shares["float_shares"] > 0]
    if free_shares.empty:
        return None
    shares = free_shares.pivot_table(
        index="date", columns="code", values="float_shares", aggfunc="last"
    )
    shares.index = pd.to_datetime(shares.index)
    shares = shares.sort_index()
    common = volume_panel.columns.intersection(shares.columns)
    if common.empty:
        return None
    aligned = (
        shares[common]
        .reindex(shares.index.union(volume_panel.index))
        .ffill()
        .reindex(volume_panel.index)
    )
    # 成交额/价格 → 股数不可得；直接用成交量(股) / 流通股本
    return volume_panel[common].div(aligned.replace(0, np.inf)) * 100.0


def load_instrument_frame() -> pd.DataFrame | None:
    """最新合约详情：DataFrame(index=code, columns=[name, list_date, up_stop, down_stop])

    仅取实际存在的列（导入的历史快照可能缺 up_stop/down_stop）。
    """
    df = _read(_INSTRUMENT_FILE)
    if df is None or df.empty:
        return None
    latest = df.sort_values("date").drop_duplicates("code", keep="last")
    keep = [c for c in ("name", "list_date", "up_stop", "down_stop") if c in latest.columns]
    return latest.set_index("code")[keep]


def build_st_status(dates, codes) -> pd.DataFrame | None:
    """逐日 as-of ST 状态：True=ST（index=日期, columns=代码）

    基于 instrument 快照（date, code, name）：ST 状态从「含 ST 名称的快照日」起
    生效并前向填充——今天才快照到的 *ST 名称不会倒灌到 2015 年截面（避免用未来
    信息）；早于首次快照的日期无 ST 信息 → False（不排除，调用方用 assumptions
    明示该局限）。代码从未出现于快照 → False。
    """
    df = _read(_INSTRUMENT_FILE)
    if df is None or df.empty or "name" not in df.columns:
        return None
    snap = df[["date", "code", "name"]].copy()
    snap["is_st"] = snap["name"].fillna("").str.upper().str.contains("ST")
    snap_dates = pd.to_datetime(snap["date"]).dt.normalize()
    pivot = snap.pivot_table(
        index=snap_dates, columns="code", values="is_st", aggfunc="any"
    )
    if pivot.empty:
        return None
    pivot = pivot.reindex(columns=codes)
    target = pd.DatetimeIndex(pd.to_datetime(dates)).normalize()
    all_dates = pd.DatetimeIndex(sorted(set(pivot.index) | set(target)))
    aligned = pivot.reindex(all_dates).ffill().reindex(target)
    # nullable boolean 填充：避免 object dtype 隐式 downcast 警告
    return aligned.astype("boolean").fillna(False).astype(bool)


# ── 派生面板（可交易掩码 / 涨跌停近似价） ─────────────────────────


def build_tradable_mask(volume_panel: pd.DataFrame) -> pd.DataFrame:
    """可交易掩码：成交量>0 视为可交易（volume==0 或缺数据推断为停牌）"""
    return volume_panel.fillna(0.0) > 0


def limit_pct_for_code(code: str, name: str = "") -> float:
    """按板归类的涨跌停幅度近似：ST±5%、创业/科创±20%、北交所±30%、主板±10%"""
    if "ST" in name.upper():
        return 0.05
    if code.endswith(".BJ"):
        return 0.30
    prefix = code.split(".")[0][:3]
    if prefix in ("300", "301", "302", "688", "689"):
        return 0.20
    return 0.10


def build_limit_prices(
    close_panel: pd.DataFrame,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """涨跌停近似价：昨收 ×(1±板块幅度)，四舍五入至分

    幅度：ST 5%（逐日 as-of 状态，instrument 快照生效日起）、创业/科创 20%、
    北交所 30%、主板 10%。历史涨跌停价 QMT 不提供，按板归类近似；
    早于首次快照的区间无 ST 状态 → 按非 ST 幅度（调用方以 assumptions 明示）。
    """
    base_pcts = pd.Series(
        {c: limit_pct_for_code(c, "") for c in close_panel.columns}
    )
    pcts = pd.DataFrame(
        np.tile(base_pcts.to_numpy(), (len(close_panel), 1)),
        index=close_panel.index,
        columns=close_panel.columns,
        dtype=float,
    )
    st_status = build_st_status(close_panel.index, close_panel.columns)
    if st_status is not None:
        pcts[st_status] = 0.05
    prev_close = close_panel.shift(1)
    up = (prev_close * (1 + pcts)).round(2)
    down = (prev_close * (1 - pcts)).round(2)
    return up, down

"""AI/用户信号代码执行 — OpenSandbox 容器隔离，Docker 不可用时降级进程内

方案（与用户确认）：
- 现成轮子 OpenSandbox（阿里，Apache-2.0），容器级隔离，支持 Windows（Docker
  Desktop + WSL2 后端）；不挂载数据卷（Windows 路径易踩坑），改用其文件 API
  把本次回测需要的行情面板以 CSV 传入沙箱，跑完把信号 CSV 读回宿主机。
- 仅用于 QUBE / 回测相关的代码执行（/backtest/run-strategy 与 QUBE run_backtest 工具）。
- Docker / opensandbox-server 不可用时：降级为进程内执行 + 明确警告（不阻断），
  该时刻无容器隔离；执行不设超时（回测本就重）。

区分两类失败：
- SandboxInfraError：沙箱基础设施不可用（未装包 / 未起 server / Docker 未就绪）→ 降级
- ValueError：用户信号代码本身有问题（未定义函数 / 运行报错）→ 直接上抛给调用方
"""

import asyncio
import io
import time
from urllib.parse import urlparse

import pandas as pd
from loguru import logger

from backend.config import settings


class SandboxInfraError(RuntimeError):
    """沙箱基础设施不可用（触发降级，不代表用户代码有错）"""


# 沙箱内运行的信号执行脚本：读入行情 CSV → 执行用户代码 → 调 generate_signals →
# 结果写出 CSV；用户代码异常以 SIGNAL_ERROR 前缀输出到 stdout，供宿主机识别
_RUNNER_TEMPLATE = """\
import sys, traceback
import pandas as pd
import numpy as np

prices = pd.read_csv({prices_path!r}, index_col=0, parse_dates=True)
_user_ns = {{"pd": pd, "np": np}}
try:
    exec({code!r}, _user_ns)
    fn = _user_ns.get("generate_signals")
    if not callable(fn):
        print("SIGNAL_ERROR:信号代码必须定义 generate_signals(prices, **kwargs) 函数")
        sys.exit(0)
    sig = fn(prices)
    if isinstance(sig, dict):
        sig = pd.DataFrame.from_dict(sig, orient="index")
    if not isinstance(sig, pd.DataFrame):
        print("SIGNAL_ERROR:generate_signals 应返回 dict 或 DataFrame")
        sys.exit(0)
    sig.to_csv({signals_path!r})
    print("SIGNAL_OK")
except Exception as e:
    print("SIGNAL_ERROR:" + str(e))
    traceback.print_exc()
"""


def _normalize_signals(sig) -> pd.DataFrame:
    """把 generate_signals 的返回值统一成按日期排序的面板 DataFrame"""
    if isinstance(sig, dict):
        df = pd.DataFrame.from_dict(sig, orient="index")
        df.index = pd.to_datetime(df.index)
        return df.sort_index()
    if isinstance(sig, pd.DataFrame):
        return sig
    raise ValueError("generate_signals 应返回 dict 或 DataFrame")


def sandbox_available() -> bool:
    """沙箱是否可能可用（配置开启 + opensandbox 包可导入）；真实可达性在执行时判定"""
    if not settings.sandbox_enabled:
        return False
    try:
        import opensandbox  # noqa: F401
    except Exception:
        return False
    return True


async def _run_in_opensandbox(signal_code: str, prices: pd.DataFrame) -> pd.DataFrame:
    """在 OpenSandbox 容器中执行信号代码，返回信号面板

    任何基础设施层失败抛 SandboxInfraError（触发降级）；用户代码错误抛 ValueError。
    """
    try:
        from opensandbox import Sandbox
        from opensandbox.models import WriteEntry
    except Exception as e:  # 包未安装 → 降级
        raise SandboxInfraError(f"opensandbox 未安装: {e}")

    prices_csv = prices.to_csv()
    prices_path = "/tmp/lq_prices.csv"
    signals_path = "/tmp/lq_signals.csv"
    runner = _RUNNER_TEMPLATE.format(
        prices_path=prices_path, signals_path=signals_path, code=signal_code
    )
    runner_path = "/tmp/lq_runner.py"

    try:
        sandbox = await Sandbox.create(settings.sandbox_image)
    except Exception as e:  # server/Docker 不可用 → 降级
        raise SandboxInfraError(
            f"创建沙箱失败（Docker/opensandbox-server 未就绪？）: {e}"
        )

    try:
        async with sandbox:
            await sandbox.files.write_files(
                [
                    WriteEntry(path=prices_path, data=prices_csv, mode=644),
                    WriteEntry(path=runner_path, data=runner, mode=644),
                ]
            )
            execution = await sandbox.commands.run(f"python {runner_path}")
            stdout = _collect_stdout(execution)
            if "SIGNAL_ERROR:" in stdout:
                msg = stdout.split("SIGNAL_ERROR:", 1)[1].splitlines()[0].strip()
                raise ValueError(f"信号代码执行失败: {msg}")
            content = await sandbox.files.read_file(signals_path)
            text = (
                content.decode()
                if isinstance(content, (bytes, bytearray))
                else str(content)
            )
            return pd.read_csv(io.StringIO(text), index_col=0, parse_dates=True)
    except ValueError:
        raise
    except SandboxInfraError:
        raise
    except Exception as e:  # 执行/读写过程的基础设施异常 → 降级
        raise SandboxInfraError(f"沙箱执行异常: {e}")


def _collect_stdout(execution) -> str:
    """兼容 OpenSandbox 不同返回结构，尽量取出 stdout 文本"""
    try:
        logs = getattr(execution, "logs", None)
        out = getattr(logs, "stdout", None) if logs is not None else None
        if isinstance(out, list):
            return "\n".join(getattr(x, "text", str(x)) for x in out)
        if out is not None:
            return str(out)
        return str(getattr(execution, "stdout", "") or execution)
    except Exception:
        return str(execution)


def _run_in_process(signal_code: str, prices: pd.DataFrame) -> pd.DataFrame:
    """进程内执行（降级路径 / 无 Docker 时）：与沙箱不可用前的原行为一致，不加限制"""
    import numpy as np

    exec_ctx: dict = {}
    exec(signal_code, {"__builtins__": __builtins__, "pd": pd, "np": np}, exec_ctx)  # noqa: S102
    fn = exec_ctx.get("generate_signals")
    if not callable(fn):
        raise TypeError("信号代码必须定义 generate_signals(prices, **kwargs) 函数")
    return _normalize_signals(fn(prices))


async def run_signals(
    signal_code: str, prices: pd.DataFrame
) -> tuple[pd.DataFrame, bool]:
    """执行信号代码，返回 (信号面板, 是否在沙箱中隔离执行)

    - 沙箱可用：容器内执行；用户代码错误抛 ValueError；基础设施故障自动降级
    - 沙箱不可用：进程内执行 + 警告日志
    """
    if sandbox_available():
        try:
            df = await _run_in_opensandbox(signal_code, prices)
            return _normalize_signals(df), True
        except SandboxInfraError as e:
            logger.warning(f"OpenSandbox 不可用，降级为进程内执行（无容器隔离）：{e}")

    import asyncio

    df = await asyncio.to_thread(_run_in_process, signal_code, prices)
    return df, False


_status_cache: dict = {"ts": 0.0, "server_reachable": False, "probe_error": ""}
_STATUS_TTL = 15.0


async def _probe_server() -> tuple[bool, str]:
    """探测 opensandbox-server 是否实际可达（轻量 HTTP，短超时）

    只判断 server 进程/端口是否活着；Docker 与镜像是否可用仍需首次
    创建沙箱时确认，因此返回「可达」而非「保证可用」。
    """
    domain = (settings.sandbox_server_domain or "localhost:8080").strip()
    base = domain if domain.startswith(("http://", "https://")) else f"http://{domain}"
    parsed = urlparse(base)
    host = parsed.hostname or "localhost"
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    error = ""

    try:
        import httpx

        async with httpx.AsyncClient(timeout=1.5) as client:
            for path in ("/v1/ping", "/ping", "/health", "/"):
                url = f"{parsed.scheme}://{host}:{port}{path}"
                try:
                    resp = await client.get(url)
                    if resp.status_code < 500:
                        return True, ""
                except Exception as e:
                    error = str(e)[:160]
    except Exception as e:
        error = str(e)[:160]

    # HTTP 探测失败时退回 TCP 探测，区分「端口通但无健康响应」
    try:
        _, writer = await asyncio.wait_for(
            asyncio.open_connection(host, port), timeout=1.2
        )
        writer.close()
        try:
            await writer.wait_closed()
        except Exception:
            pass
        return False, f"端口 {host}:{port} 可达，但未返回健康响应"
    except Exception as e:
        return False, error or str(e)[:160]


async def sandbox_status() -> dict:
    """沙箱状态（供前端/接口展示；实际探测 server，不把「可能可用」当「就绪」）"""
    now = time.time()
    if now - _status_cache["ts"] > _STATUS_TTL:
        server_reachable, probe_error = await _probe_server()
        _status_cache.update(
            {
                "ts": now,
                "server_reachable": server_reachable,
                "probe_error": probe_error,
            }
        )

    available = sandbox_available()
    server_reachable = bool(_status_cache.get("server_reachable"))
    active = available and server_reachable
    if not available:
        note = "未启用/未安装 opensandbox，回测信号将进程内执行（无容器隔离）"
    elif active:
        note = (
            "opensandbox-server 可达；Docker/镜像最终可用性以首次沙箱创建为准，"
            "失败时自动降级进程内执行"
        )
    else:
        err = _status_cache.get("probe_error") or "server 不可达"
        note = (
            f"opensandbox-server 不可达（{err}）；回测信号将进程内执行"
            "（无容器隔离）"
        )
    return {
        "enabled": settings.sandbox_enabled,
        "package_installed": _pkg_installed(),
        "server_reachable": server_reachable,
        "active": active,
        "image": settings.sandbox_image,
        "note": note,
        "probe_error": _status_cache.get("probe_error", ""),
    }


def _pkg_installed() -> bool:
    try:
        import opensandbox  # noqa: F401
    except Exception:
        return False
    return True

"""Parquet 本地缓存管理

存储结构: data/cache/{period}/{code}.parquet
支持增量追加、去重合并、缓存统计。
"""
from __future__ import annotations

from pathlib import Path

import pandas as pd
from loguru import logger

from backend.config import settings


class DataCache:
    """基于 Parquet 的本地数据缓存"""

    def __init__(self, cache_dir: Path | None = None):
        self._cache_dir = cache_dir or settings.cache_dir
        self._cache_dir.mkdir(parents=True, exist_ok=True)

    # ── 路径 ─────────────────────────────────────────────────

    def _get_path(self, code: str, period: str) -> Path:
        """获取缓存文件路径（code 中 '.' 替换为 '_'）"""
        safe_code = code.replace(".", "_")
        period_dir = self._cache_dir / period
        period_dir.mkdir(parents=True, exist_ok=True)
        return period_dir / f"{safe_code}.parquet"

    # ── 读取 ─────────────────────────────────────────────────

    def get(self, code: str, period: str) -> pd.DataFrame | None:
        """读取缓存数据，不存在则返回 None"""
        path = self._get_path(code, period)
        if not path.exists():
            return None
        try:
            df = pd.read_parquet(path)
            return df
        except Exception as e:
            logger.warning(f"Failed to read cache {path}: {e}")
            return None

    # ── 写入 ─────────────────────────────────────────────────

    def save(self, code: str, period: str, df: pd.DataFrame):
        """保存 DataFrame 到 Parquet 缓存"""
        if df.empty:
            return
        path = self._get_path(code, period)
        try:
            df.to_parquet(path, engine="pyarrow", index=True)
            logger.debug(f"Cache saved: {path} ({len(df)} rows)")
        except Exception as e:
            logger.warning(f"Failed to save cache {path}: {e}")

    # ── 增量更新 ─────────────────────────────────────────────

    def get_or_append(self, code: str, period: str, new_df: pd.DataFrame) -> pd.DataFrame:
        """增量更新：合并新数据并去重

        如果已有缓存，合并后按索引去重（保留最新）；
        如果无缓存，直接保存新数据。
        """
        if new_df.empty:
            existing = self.get(code, period)
            return existing if existing is not None else pd.DataFrame()

        existing = self.get(code, period)
        if existing is None:
            self.save(code, period, new_df)
            return new_df.copy()

        # 合并并按索引去重（保留后面的新数据）
        combined = pd.concat([existing, new_df])
        combined = combined[~combined.index.duplicated(keep="last")]
        combined = combined.sort_index()
        self.save(code, period, combined)
        return combined.copy()

    # ── 查询 ─────────────────────────────────────────────────

    def get_latest_timestamp(self, code: str, period: str) -> str | None:
        """获取缓存中最新一条数据的时间戳（字符串形式）"""
        df = self.get(code, period)
        if df is None or df.empty:
            return None
        try:
            latest = df.index[-1]
            return str(latest)
        except Exception:
            return None

    # ── 失效 ─────────────────────────────────────────────────

    def invalidate(self, code: str, period: str):
        """删除指定缓存文件"""
        path = self._get_path(code, period)
        if path.exists():
            try:
                path.unlink()
                logger.info(f"Cache invalidated: {path}")
            except Exception as e:
                logger.warning(f"Failed to invalidate cache {path}: {e}")

    # ── 统计 ─────────────────────────────────────────────────

    def cache_status(self) -> dict:
        """统计缓存状态：文件数、总大小、按周期分组"""
        total_files = 0
        total_size = 0
        by_period: dict[str, dict] = {}

        if not self._cache_dir.exists():
            return {"total_files": 0, "total_size_bytes": 0, "by_period": {}}

        for period_dir in sorted(self._cache_dir.iterdir()):
            if not period_dir.is_dir():
                continue
            period_name = period_dir.name
            files = list(period_dir.glob("*.parquet"))
            if not files:
                continue
            dir_size = sum(f.stat().st_size for f in files if f.exists())
            by_period[period_name] = {
                "files": len(files),
                "size_bytes": dir_size,
            }
            total_files += len(files)
            total_size += dir_size

        return {
            "total_files": total_files,
            "total_size_bytes": total_size,
            "by_period": by_period,
        }
"""数据标准化工具

提供时间戳转换、字段名映射、DataFrame 序列化等通用功能。
"""
from __future__ import annotations

from datetime import UTC, datetime

import pandas as pd


def conv_time(timestamp_ms: float) -> str:
    """毫秒时间戳转 "20240101150000" 格式字符串

    Args:
        timestamp_ms: 毫秒级时间戳

    Returns:
        "YYYYMMDDHHmmss" 格式字符串
    """
    dt = datetime.fromtimestamp(timestamp_ms / 1000.0, tz=UTC)
    return dt.strftime("%Y%m%d%H%M%S")


def normalize_timestamp(index: pd.Index) -> pd.DatetimeIndex:
    """将各种时间索引统一转为 Asia/Shanghai 无时区 DatetimeIndex。

    QMT 行情时间戳均为北京时间；epoch 毫秒/秒若按 UTC 解释会让分钟 bar
    产生 8 小时时移。统一转到 Asia/Shanghai 后再丢弃时区，避免下游
    再做 tz_localize(None) 时保留错误时刻。
    """
    if isinstance(index, pd.DatetimeIndex):
        if index.tz is not None:
            return index.tz_convert("Asia/Shanghai").tz_localize(None)
        return index

    # 整数/浮点索引 → epoch 时间戳；按量级区分毫秒/秒
    if pd.api.types.is_integer_dtype(index) or pd.api.types.is_float_dtype(index):
        values = pd.Series(pd.to_numeric(index, errors="coerce")).dropna()
        max_abs = float(values.abs().max()) if len(values) else 0.0
        unit = "ms" if max_abs > 1e11 else "s"
        return (
            pd.to_datetime(index.astype("int64"), unit=unit, utc=True)
            .tz_convert("Asia/Shanghai")
            .tz_localize(None)
        )

    # 字符串或其他 → 尝试解析（字符串由 QMT 给出时通常已是北京时间）
    return pd.to_datetime(index)


def normalize_kline_fields(df: pd.DataFrame) -> pd.DataFrame:
    """K 线字段名标准化

    将 xtquant 返回的字段名统一为小写下划线风格。
    常见映射: open/high/low/close/volume/amount 等。
    """
    if df.empty:
        return df

    rename_map: dict[str, str] = {}
    col_lower = {c.lower(): c for c in df.columns}

    # 标准字段映射（xtquant 原始 → 标准化）
    field_aliases = {
        "open": ["open", "开盘价", "开盘"],
        "high": ["high", "最高价", "最高"],
        "low": ["low", "最低价", "最低"],
        "close": ["close", "收盘价", "收盘"],
        "volume": ["volume", "vol", "成交量", "成交量(手)"],
        "amount": ["amount", "成交额", "成交额(元)"],
        "turnover": ["turnover", "换手率"],
    }

    for standard_name, aliases in field_aliases.items():
        for alias in aliases:
            if alias in col_lower and alias != standard_name:
                rename_map[col_lower[alias]] = standard_name
                break

    df = df.rename(columns=rename_map)
    return df


def normalize_tick_fields(df: pd.DataFrame) -> pd.DataFrame:
    """Tick 字段名标准化

    将 xtquant tick 数据的字段名统一。
    """
    if df.empty:
        return df

    rename_map: dict[str, str] = {}
    col_lower = {c.lower(): c for c in df.columns}

    tick_aliases = {
        "last_price": ["lastprice", "last_price", "最新价", "现价"],
        "open": ["open", "开盘价"],
        "high": ["high", "最高价"],
        "low": ["low", "最低价"],
        "volume": ["volume", "vol", "成交量", "总量"],
        "amount": ["amount", "成交额", "总金额"],
        "bid_price": ["bidprice", "bid_price"],
        "ask_price": ["askprice", "ask_price"],
        "bid_vol": ["bidvol", "bid_vol"],
        "ask_vol": ["askvol", "ask_vol"],
    }

    for standard_name, aliases in tick_aliases.items():
        for alias in aliases:
            if alias in col_lower and alias != standard_name:
                rename_map[col_lower[alias]] = standard_name
                break

    df = df.rename(columns=rename_map)
    return df


def df_to_serializable(df: pd.DataFrame) -> dict:
    """将 DataFrame 转为 JSON 可序列化格式

    Returns:
        {"columns": [...], "index": [...], "data": [[...], ...]}
    """
    if df.empty:
        return {"columns": [], "index": [], "data": []}

    # 处理索引
    index_values = []
    for v in df.index:
        if isinstance(v, pd.Timestamp):
            index_values.append(v.isoformat())
        else:
            index_values.append(str(v))

    # 处理数据（NaN → None）
    data = []
    for row in df.itertuples(index=False):
        data.append([
            None if (isinstance(v, float) and pd.isna(v)) else v
            for v in row
        ])

    return {
        "columns": list(df.columns),
        "index": index_values,
        "data": data,
    }

"""财务数据服务 — 公告日(point-in-time)基本面，防前视

从 QMT 拉取财务数据（Income/Balance/Pershareindex 等），以【公告日 m_anntime】
为可用时点构建截面面板，保证研究日 T 只能用 T 之前【已披露】的财报，杜绝前视。

存储: data/cache/fundamental/{code}.parquet, 每表一行含:
    timetag(报告截止日) / anntime(公告日) / 及各指标列

本文件所有内存逻辑不依赖 QMT，可用合成数据测试。
"""

from __future__ import annotations

import pandas as pd
from loguru import logger

from backend.config import settings

FUND_DIR = settings.cache_dir / "fundamental"

# 统一收入/占位数比较常用的指标；持久化时只用以下字段（前端也按此展示）
FUND_FIELDS = [
