    "roe",            # 净资产收益率
    "pb",             # 市净率(每股净资产可换算)
    "net_profit",
    "revenue",
    "total_assets",
    "total_liab",
    # 现金流（Cashflow 表；2026-08 起快照拉取该表，供现金流/质量因子使用）
    "operating_cashflow",
    "total_cashflow",
]

# QMT 各报表字段名到统一字段的别名映射（小写匹配；xtquant 版本间命名不一致）
FIELD_ALIASES = {
    "eps": ["basiceps", "epsbasics", "earningspershare"],
    "roe": ["returnonequity", "netprofitratio"],
    "pb": ["pricebookratio", "pbratio"],
    "net_profit": ["netprofit", "profitaftertax"],
    "revenue": ["operatingrevenue", "revenue_operate"],
    "total_assets": ["totalasset", "totalassetss"],
    "total_liab": ["totalliabilities", "totaldebt"],
    "operating_cashflow": [
        "operatingnetcashflow",
        "netcashflowfromoperating",
        "cashflowfromoperatingactivities",
        "netoperatingcashflow",
        "cfo",
    ],
    "total_cashflow": [
        "totalnetcashflow",
        "netincreaseincash",
        "netincreasecashflow",
        "netchangeincash",
    ],
}


def _canonical_field(col: str) -> str | None:
    """列名 → 统一字段名（先精确匹配 FUND_FIELDS，再按别名表归一），无则 None"""
    lower = str(col).lower()
    for f in FUND_FIELDS:
        if lower == f:
            return f
    for field, aliases in FIELD_ALIASES.items():
        if lower in aliases:
            return field
    return None


def snapshot_status() -> dict:
    """本地基本面快照状态（供两端标注 fund_* 可用性）。不读大文件，只扫目录。"""
    d = FUND_DIR
    codes = []
    if d.is_dir():
        codes = [p.stem.replace("_", ".") for p in d.glob("*.parquet")]
    return {"rows": len(codes), "codes": codes, "ready": bool(codes)}


def _ensure_dir():
    FUND_DIR.mkdir(parents=True, exist_ok=True)


def snapshot_fundamental(qmt, codes: list[str]) -> int:
    """批量拉取并落盘；QMT 需连接。返回记录数。"""
    from backend.data.qmt_client import QMTClient
    if not (isinstance(qmt, QMTClient) and qmt.connected):
        logger.warning("财务数据快照：QMT 未连接，跳过")
        return 0
    _ensure_dir()
    records = 0
    tables = ["Pershareindex", "Income", "Balance", "CostCapital", "Cashflow"]
    for code in codes:
        try:
            data = qmt.get_financial(
                [code], tables=tables, report_type="announce_time"
            )
            frames = _code_frames(data.get(code))
            if not frames:
                continue
            merged = _merge_frames(frames)
            if merged.empty:
                continue
            safe = code.replace(".", "_")
            merged.to_parquet(FUND_DIR / f"{safe}.parquet", index=False)
            records += len(merged)
        except Exception as e:
            logger.warning(f"财务数据快照失败 {code}: {e}")
    return records


def _code_frames(code_tables) -> dict[str, pd.DataFrame]:
    out = {}
    for table, df in (code_tables or {}).items():
        if isinstance(df, pd.DataFrame) and not df.empty:
            out[table] = df
    return out


def _merge_frames(frames: dict[str, pd.DataFrame]) -> pd.DataFrame:
    """把多张财务表按公告日合并成一张宽表：columns=字段, row 为公告日, 升序

    以 anntime 为连接键、按表优先级（Pershareindex > Income > Balance > CostCapital）
    合并各表呈现的指标，避免 `pd.concat(axis=1)` 造成的重复列（各表都带 anntime，
    eps 又同时出现在 Pershareindex/Income）导致无法落盘。
    """
    _PRIORITY = ["Pershareindex", "Income", "Balance", "CostCapital", "Cashflow"]
    order = {p: i for i, p in enumerate(_PRIORITY)}
    parts: list[pd.DataFrame] = []
    for table, df in frames.items():
        ann = _find_col(df, ["m_anntime", "announce_time", "mAnnounce", "anntime"])
        if ann is None:
            continue
        keep = set()
        rename_map: dict[str, str] = {}
        for c in df.columns:
            canon = _canonical_field(c)
            if canon is not None:
                keep.add(c)
                rename_map[c] = canon
        if not keep:
            continue
        ren = {}
        if ann != "anntime":
            ren[ann] = "anntime"
        sub = df[list(keep | {ann})].copy().rename(columns={**ren, **rename_map})
        sub["_table"] = order.get(table, 99)
        parts.append(sub)
    if not parts:
        return pd.DataFrame()

    rows = sorted(parts, key=lambda s: int(s.iloc[0]["_table"]) if len(s) else 0)
    if not rows:
        return pd.DataFrame()
    merged = rows[0].drop(columns="_table")
    for r in rows[1:]:
        r = r.drop(columns="_table")
        merged = pd.merge(
            merged, r, on="anntime", how="outer", suffixes=("", "_dup")
        )
        merged = merged[[c for c in merged.columns if not c.endswith("_dup")]]
    if "anntime" not in merged.columns:
        return pd.DataFrame()
    merged = merged.sort_values("anntime")
    return merged


def _find_col(df: pd.DataFrame, candidates: list[str]) -> str | None:
    lower = {str(c).lower(): c for c in df.columns}
    for cand in candidates:
        if cand.lower() in lower:
            return lower[cand.lower()]
    return None


def load_code_fundamental(code: str) -> pd.DataFrame | None:
    """读取单只股票基本面（含 anntime），无则 None"""
    safe = code.replace(".", "_")
    path = FUND_DIR / f"{safe}.parquet"
    if not path.exists():
        return None
    try:
        return pd.read_parquet(path)
    except Exception as e:
        logger.warning(f"读取基本面 {path} 失败: {e}")
        return None


def build_fundamental_panels(
    codes: list[str], trade_dates: pd.DatetimeIndex, fund_dir=None
) -> dict[str, pd.DataFrame]:
    """按公告日 ffill 构建各指标的点位面板 {field: DataFrame(index=date, columns=code)}

    任一 trading_day 上，某只股票取「公告日 <= 该日」的最近一期值；无则 NA。

    Args:
        codes: 股票代码
        trade_dates: 研究交易日期序列
        fund_dir: 覆盖数据目录（测试用）
    """
    panels: dict[str, dict] = {f: {} for f in FUND_FIELDS}
    d = FUND_DIR if fund_dir is None else fund_dir

    for code in codes:
        safe = code.replace(".", "_")
        path = d / f"{safe}.parquet"
        if not path.exists():
            continue
        try:
            df = pd.read_parquet(path)
        except Exception:
            continue
        ann = None
        for c in df.columns:
            if str(c).lower() in ("anntime", "m_anntime", "ann", "annt", "nt"):
                ann = c
                break
        if ann is None:
            continue
        col = df[ann]
        if pd.api.types.is_numeric_dtype(col):
            # 数值：假设毫秒 epoch（QMT 时间戳）；< 10^12 视为秒
            unit = "ms" if (col.dropna().abs() > 1e12).any() else "s"
            ts = pd.to_datetime(col, unit=unit, errors="coerce")
        else:
            ts = pd.to_datetime(col, errors="coerce")
        for f in FUND_FIELDS:
            if f in df.columns and ts.notna().any():
                s = pd.Series(df[f].values, index=ts.values)
                s = s[ts.notna().values]
                # 按公告日升序、取每个公告日最近值 → 落到 trade_dates 上 ffill
                s = s[~s.index.duplicated(keep="last")]
                s = s.sort_index()
                s = s.reindex(trade_dates, method="ffill").astype(float, errors="ignore")
                panels[f][code] = s.reindex(trade_dates)

    out = {}
    for f, d1 in panels.items():
        if d1:
            frame = pd.DataFrame(d1).sort_index()
            out[f] = frame
    return out


def inject_fundamental_namespace(panels: dict) -> dict:
    """给 limit obj express via fundamental 面板注入到命名空间（如 fund.pe ...）

    Args:
        s: 现有求值命名空间
    Returns:
        新增的 {fund_xxx: panel} 或 {fund: {}}。
    """
    return {f"fund_{f}": p for f, p in panels.items()}"""批量数据下载服务 — 板块/指数/代码列表批量下载，SSE 逐只进度

事件类型（与工作流 runner 的 SSE 风格一致）：
  batch_start:     {total, codes}
  symbol_complete: {index, code, rows}
  symbol_failed:   {index, code, error}
  reference_saved: {kind, rows}          参考数据快照结果（非致命）
  batch_complete:  {ok, failed, failed_codes, duration_ms}

QMT 调用为同步阻塞，逐只放入线程池避免卡住事件循环；
每只失败自动重试一次，最终失败进入 failed_codes 供前端重试。
"""

from __future__ import annotations

import asyncio
import json
import time
from collections.abc import AsyncGenerator
from datetime import datetime
from typing import Any

from loguru import logger

from backend.services import market_data, reference_data


def _sse(event_type: str, data: dict[str, Any]) -> str:
    data.setdefault("timestamp", datetime.now().astimezone().isoformat())
    payload = json.dumps(data, ensure_ascii=False, default=str)
    return f"event: {event_type}\ndata: {payload}\n\n"


def expand_sector(sector: str) -> list[str]:
    """展开板块/指数成分股（需 QMT 连接）"""
    qmt = market_data._qmt
    if not qmt.connected:
        raise ConnectionError("QMT 未连接，无法展开板块成分")
    stocks = qmt.get_sector_stocks(sector)
    if not stocks:
        raise ValueError(f"板块「{sector}」无成分股或不存在")
    return stocks


def _download_one(code: str, period: str, start: str, end: str) -> int:
    """下载单只并合并入缓存，返回缓存总行数

    存储语义：不复权 OHLCV + adjust_factor（由后复权价反推，锚定上市日，
    增量缓存自洽）；旧版前复权缓存（无 adjust_factor 列）无法逆推不复权价，
    合并前整体丢弃重建，保证帧内口径一致。
    """
    from backend.services import market_data

    qmt = market_data._qmt
    qmt.download_history([code], period=period, start_time=start, end_time=end)
    raw = qmt.get_kline(
        [code], period=period, start_time=start, end_time=end, dividend_type="none"
    ).get(code)
    if raw is None or raw.empty:
        raise ValueError("QMT 未返回数据")
    raw = market_data.normalize_kline_fields(raw)
    back = qmt.get_kline(
        [code], period=period, start_time=start, end_time=end, dividend_type="back"
    ).get(code)
    if back is None or back.empty:
        logger.warning(f"{code} 后复权数据缺失，adjust_factor 置 1（按不复权存储）")
        raw = raw.copy()
        raw["adjust_factor"] = 1.0
    else:
        raw = market_data._merge_with_factor(raw, market_data.normalize_kline_fields(back))

    existing = market_data._cache.get(code, period)
    if existing is not None and "adjust_factor" not in existing.columns:
        # 旧版前复权缓存：口径不可逆，整体丢弃重建（新帧为准，提示区间可能变短）
        market_data._cache.invalidate(code, period)
        logger.info(f"{code} 旧版前复权缓存已重建为 不复权+adjust_factor 存储")
        merged = raw.copy()
    else:
        merged = market_data._cache.get_or_append(code, period, raw)
    return len(merged)


async def batch_download_stream(
    codes: list[str],
    period: str = "1d",
    start_date: str = "",
    end_date: str = "",
    sector: str = "",
    per_code_start: dict[str, str] | None = None,
) -> AsyncGenerator[str, None]:
    """批量下载 SSE 生成器

    Args:
        codes: 代码列表（已展开）
        sector: 非空时下载完成后记录该板块的成分快照
        per_code_start: 增量补齐模式下每只股票各自的起始日期（yyyymmdd）
    """
    qmt = market_data._qmt
    if not qmt.connected:
        yield _sse(
            "batch_failed",
            {
                "status": "failed",
                "message": "QMT 未连接，无法下载数据 — xtquant 仅 Windows 可用",
            },
        )
        return

    start = start_date.replace("-", "")
    end = end_date.replace("-", "")
    started = time.perf_counter()

    yield _sse("batch_start", {"total": len(codes), "codes": codes})

    ok = 0
    failed_codes: list[str] = []
    for i, code in enumerate(codes):
        code_start = (per_code_start or {}).get(code, start)
        error: str = ""
        rows = 0
        # 每只失败自动重试一次
        for attempt in range(2):
            try:
                rows = await asyncio.to_thread(
                    _download_one, code, period, code_start, end
                )
                error = ""
                break
            except Exception as e:
                error = str(e)
                logger.warning(f"下载 {code} 失败（第 {attempt + 1} 次）: {e}")
        if error:
            failed_codes.append(code)
            yield _sse(
                "symbol_failed",
                {"index": i, "code": code, "error": error, "level": "error"},
            )
        else:
            ok += 1
            yield _sse("symbol_complete", {"index": i, "code": code, "rows": rows})

    # 参考数据快照（非致命：失败只记录，不影响行情下载结果）
    downloaded = [c for c in codes if c not in failed_codes]
    async for event in _snapshot_reference(sector, downloaded):
        yield event

    yield _sse(
        "batch_complete",
        {
            "ok": ok,
            "failed": len(failed_codes),
            "failed_codes": failed_codes,
            "duration_ms": int((time.perf_counter() - started) * 1000),
        },
    )


async def _snapshot_reference(
    sector: str, codes: list[str]
) -> AsyncGenerator[str, None]:
    """采集参考数据快照并逐项 yield 结果事件"""
    qmt = market_data._qmt
    if not qmt.connected or not codes:
        return

    tasks: list[tuple[str, Any]] = [
        ("instrument", lambda: reference_data.snapshot_instrument(qmt, codes)),
        ("capital", lambda: reference_data.snapshot_capital(qmt, codes)),
        ("industry", lambda: reference_data.snapshot_industry(qmt)),
        ("major_indices", lambda: reference_data.snapshot_major_indices(qmt)),
        ("universe_pools", lambda: reference_data.snapshot_universe_pools(qmt)),
    ]
    if sector:
        tasks.insert(
            0,
            (
                "index_constituents",
                lambda: reference_data.snapshot_index_constituents(qmt, sector),
            ),
        )

    for kind, fn in tasks:
        try:
            rows = await asyncio.to_thread(fn)
            yield _sse("reference_saved", {"kind": kind, "rows": rows})
        except Exception as e:
            logger.warning(f"参考数据快照 {kind} 失败: {e}")
            yield _sse(
                "reference_saved",
                {"kind": kind, "rows": 0, "error": str(e), "level": "warning"},
            )


def build_update_plan(period: str = "1d") -> tuple[list[str], dict[str, str]]:
    """一键补齐计划：已缓存品种 → 各自末日期作为增量起点"""
    import pandas as pd

    from backend.data.converter import normalize_timestamp

    codes = market_data.list_cached_codes(period)
    per_code_start: dict[str, str] = {}
    for code in codes:
        df = market_data._cache.get(code, period)
        if df is None or df.empty:
            continue
        try:
            idx = normalize_timestamp(df.index)
            latest = pd.Timestamp(idx.max())
            if latest.tzinfo is not None:
                latest = latest.tz_localize(None)
            per_code_start[code] = latest.strftime("%Y%m%d")
        except Exception as e:
            logger.warning(f"解析 {code} 最新时间失败: {e}")
    return codes, per_code_start

