"""运营/批处理 API — 每日调度状态、手动重跑、分析溯源查询"""

from __future__ import annotations

import pandas as pd
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

from backend.services import provenance as provenance_svc
from backend.services import scheduler as scheduler_svc

router = APIRouter()


class RunJobsReq(BaseModel):
    steps: list[str] | None = None  # 空=全部; 传 ['market'] 或 ['recalc']


class ProvenanceWrite(BaseModel):
    kind: str = "factor"
    entity_id: str = ""
    entity_name: str = ""
    params: dict = {}
    metrics: dict = {}
    notes: str = ""
    source: str = "api"


@router.get("/scheduler")
async def scheduler_status():
    """调度配置 + 最近 job 状态"""
    try:
        return await scheduler_svc.check_status()
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/scheduler/run")
async def scheduler_run(req: RunJobsReq):
    """手动跑一轮批处理（step 缺省全跑）"""
    try:
        return await scheduler_svc.run_jobs(trigger="manual", steps=req.steps)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/provenance")
async def list_provenance(kind: str | None = None, entity_id: str | None = None, limit: int = 50):
    """查询分析溯源记录"""
    try:
        return await provenance_svc.list_provenance(kind, entity_id, limit)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/provenance")
async def write_provenance(req: ProvenanceWrite):
    """写入一条溯源记录"""
    try:
        row_id = await provenance_svc.record_provenance(
            kind=req.kind,
            entity_id=req.entity_id,
            entity_name=req.entity_name,
            params=req.params,
            metrics=req.metrics,
            notes=req.notes,
            source=req.source,
        )
        return {"id": row_id}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/briefing")
async def research_briefing():
    """每日研究简报（首页 Dashboard 展示）：市场状态 + 因子池体检 +
    近 7 日除权事件 + 数据时效 + 最近批处理状态

    全部为现有能力的实时聚合；本地无缓存时给出结构化提示而非报错。
    """
    import time

    from backend.database import get_db
    from backend.services import market_data, regime
    from backend.services.factor_research import factor_research

    briefing: dict = {
        "generated_at": int(time.time()),
        "market": None,
        "factors": None,
        "dividend_events": [],
        "data_freshness": None,
        "research_readiness": None,
        "recent_jobs": [],
    }

    # 1. 市场环境（regime 自带 15 分钟缓存 + 无指数缓存时结构化提示）
    briefing["market"] = regime.market_regime()

    # 2. 因子池体检摘要（生命周期阶段计数 + 近期衰减/失效因子）
    try:
        health = await factor_research.factor_health(min_snapshots=1)
        from collections import Counter

        stages = Counter(h["stage"] for h in health)
        briefing["factors"] = {
            "pool_n": len(health),
            "stages": dict(stages),
            "n_with_snapshot": sum(1 for h in health if h["n_snapshots"] >= 2),
            "decaying": [
                {
                    "factor_name": h["factor_name"],
                    "stage": h["stage"],
                    "latest_ic_mean": h["latest_ic_mean"],
                    "trend_label": h["trend_label"],
                }
                for h in health
                if h["stage"] in ("衰减", "失效") and h.get("latest_ic_mean") is not None
            ][:8],
        }
    except Exception:
        briefing["factors"] = {"error": "因子体检不可用"}

    # 3. 近 7 日除权事件
    try:
        briefing["dividend_events"] = market_data.dividend_events(days=7, limit=20)
    except Exception:
        pass


    # 4. 数据时效
    try:
        briefing["data_freshness"] = market_data.data_freshness()
    except Exception:
        pass

    # 4.5 研究数据就绪度：把「样本/历史/参考快照/财务/分钟」一次性讲清楚，
    # 研究员不会拿 100 只股票的样本当成全市场结论。
    try:
        from backend.config import settings
        from backend.services import fundamental, reference_data

        equity_codes = market_data.list_cached_codes("1d", exclude_indices=True)
        coverage = {
            e["code"]: e for e in market_data.cache_coverage("1d")
        }
        equity_rows = [coverage[c] for c in equity_codes if c in coverage]
        data_start = min((e["start"] for e in equity_rows if e.get("start")), default=None)
        data_end = max((e["end"] for e in equity_rows if e.get("end")), default=None)
        n_days = max((int(e.get("rows") or 0) for e in equity_rows), default=0)
        # 交易日历可得时以 QMT 交易日计；否则 n_days 只是缓存观测行数，明确标注
        trade_calendar = market_data._trading_calendar()
        calendar = "qmt" if trade_calendar else "weekday_approx"
        if trade_calendar and data_start and data_end:
            try:
                start_ts = pd.Timestamp(data_start)
                end_ts = pd.Timestamp(data_end)
                n_calendar_days = len(
                    [d for d in trade_calendar if start_ts.date() <= d <= end_ts.date()]
                )
                if n_calendar_days:
                    n_days = n_calendar_days
            except Exception:
                pass
        ref = reference_data.reference_status()
        ref_dates = [v["latest"] for v in ref.values() if v.get("latest")]
        ref_latest = max(ref_dates) if ref_dates else None

        blockers: list[str] = []
        warnings: list[str] = []
        if len(equity_codes) < 300:
            blockers.append(
                f"股票样本仅 {len(equity_codes)} 只（建议 ≥300），IC/分层/组合结果仅用于方法验证"
            )
        elif len(equity_codes) < 1000:
            warnings.append(
                f"股票样本 {len(equity_codes)} 只，建议全市场（≥1000）后再做正式因子筛选"
            )
        if n_days < 504:
            blockers.append(
                f"历史区间约 {n_days} 个交易日（建议 ≥504/2 年），尚不足以覆盖完整牛熊"
            )
        elif n_days < 756:
            warnings.append(f"历史区间约 {n_days} 个交易日，建议补充到 3 年以上")
        if ref_latest is None:
            blockers.append("无参考元数据快照（行业/成分/合约），中性化与 as-of 过滤不可用")
        elif data_end and ref_latest < str(data_end):
            warnings.append(
                f"参考快照最新日期 {ref_latest}，早于行情末日 {data_end}；"
                "历史行业/成分/ST/两融状态存在静态回填偏差"
            )
        fund = fundamental.snapshot_status()
        if not fund.get("ready"):
            warnings.append("财务快照为空，fund_* 基本面因子当前不可用")
        minute_dir = settings.cache_dir / "5m"
        minute_files = list(minute_dir.glob("*.parquet")) if minute_dir.exists() else []
        if not minute_files:
            warnings.append("无分钟缓存，日内高频因子（m_*/ID_*/M_*）不可用")
        if not market_data._qmt.connected:
            warnings.append("QMT 未连接，行情/快照无法增量更新（仅 Windows + QMT 客户端可用）")

        briefing["research_readiness"] = {
            "ready": not blockers,
            "n_stocks": len(equity_codes),
            "n_days": n_days,
            "calendar": calendar,
            "data_start": data_start,
            "data_end": data_end,
            "reference_latest": ref_latest,
            "fundamental_ready": bool(fund.get("ready")),
            "minute_ready": bool(minute_files),
            "qmt_connected": bool(market_data._qmt.connected),
            "blockers": blockers,
            "warnings": warnings,
        }
    except Exception:
        briefing["research_readiness"] = {"error": "研究数据就绪度评估不可用"}

    # 5. 最近批处理任务
    try:
        db = await get_db()
        try:
            cursor = await db.execute(
                "SELECT job_name, status, trigger, detail, started_at, finished_at "
                "FROM daily_jobs ORDER BY id DESC LIMIT 6"
            )
            briefing["recent_jobs"] = [dict(r) for r in await cursor.fetchall()]
        finally:
            await db.close()
    except Exception:
        pass

    return briefing

"""因子算子库 — 复刻 PandaAI「公式版」量化算子

设计：所有算子作用于「面板 DataFrame」(index=日期, columns=股票代码)。
- 截面算子（RANK/SCALE/ZSCORE）按行(axis=1，同一天所有股票)计算；
- 时序算子（DELAY/DELTA/MA/SUM/STD/TS_*/DECAYLINEAR...）按列(axis=0，单只股票时间序列)计算；
- 双面板算子（CORR/COV）按列做滚动配对计算。

对齐官网《PandaAI 因子编写与函数参考手册》(community/article/72)。
调用时直接用函数名（无需类名前缀），大小写均可（同时注册大写与小写别名）。
"""

from __future__ import annotations

import numpy as np
import pandas as pd


def _as_int(n) -> int:
    return int(n)


# ── 直接逐元素算子 ────────────────────────────────────────────


def ABS(x):
    return x.abs() if isinstance(x, (pd.DataFrame, pd.Series)) else np.abs(x)


def LOG(x):
    return np.log(x)


def LOGABS(x):
    return np.log(ABS(x))


def SIGN(x):
    return np.sign(x)


def SIGNEDPOWER(x, n):
    return np.sign(x) * (ABS(x) ** n)


def POWER(x, n):
    return x**n


def AS_FLOAT(x):
    return x.astype(float) if hasattr(x, "astype") else float(x)


def RD(x, n=2):
    return np.round(x, _as_int(n))


def SIN(x):
    return np.sin(x)


def COS(x):
    return np.cos(x)


def TAN(x):
    return np.tan(x)


def ARCSIN(x):
    return np.arcsin(x)


def ARCCOS(x):
    return np.arccos(x)


def ARCTAN(x):
    return np.arctan(x)


# ── 截面算子（按行 axis=1）────────────────────────────────────


def RANK(x):
    """截面排序分位数 [0,1]"""
    return x.rank(axis=1, pct=True)


def SCALE(x, a=1):
    """按截面缩放，使每行绝对值之和为 a"""
    denom = x.abs().sum(axis=1).replace(0, np.nan)
    return x.div(denom, axis=0) * a


def ZSCORE(x):
    """截面 z-score 标准化"""
    mean = x.mean(axis=1)
    std = x.std(axis=1).replace(0, np.nan)
    return x.sub(mean, axis=0).div(std, axis=0)


def INDUSTRY_NEUTRALIZE(x, industry_map=None):
    """行业中性化：逐日截面在行业内去均值（剔离行业暴露）

    industry_map: {code: industry} 行业分类映射；为空时从求值命名空间注入的
    _INDUSTRY_MAP 取（由 build_operator_namespace 填入）。无行业数据时显式报错，
    不再静默退化为全市场去均值（去均值请直接用 ZSCORE/减均值）。
    """
    if industry_map is None:
        industry_map = globals().get("_ACTIVE_INDUSTRY_MAP")
    if not industry_map:
        raise ValueError(
            "INDUSTRY_NEUTRALIZE 需要行业分类数据 — 请先在「数据管理」页下载数据以采集行业快照"
        )
    industry = pd.Series(industry_map)
    # 仅保留有行业归属且在因子列中的股票
    cols = [c for c in x.columns if c in industry.index]
    if not cols:
        raise ValueError("INDUSTRY_NEUTRALIZE：因子股票与行业分类无交集")
    sub = x[cols]
    groups = industry.reindex(cols)
    # 按行业分组做截面去均值（对每个日期/行业）
    demeaned = sub.sub(sub.T.groupby(groups).transform("mean").T)
    result = x.copy()
    result[cols] = demeaned
    return result



# ── 时序算子（按列 axis=0）────────────────────────────────────


def DELAY(x, n):
    return x.shift(_as_int(n))


REF = DELAY


def DELTA(x, n=1):
    return x - x.shift(_as_int(n))


DIFF = DELTA


def MA(x, n):
    return x.rolling(_as_int(n), min_periods=1).mean()


def SUM(x, n):
    return x.rolling(_as_int(n), min_periods=1).sum()


def SUMAC(x, n):
    """过去 N 期累计求和（同 SUM）"""
    return SUM(x, n)


def PRODUCT(x, n):
    return x.rolling(_as_int(n), min_periods=1).apply(np.prod, raw=True)


def STD(x, n):
    return x.rolling(_as_int(n), min_periods=2).std()


STDDEV = STD


def VAR(x, n):
    return x.rolling(_as_int(n), min_periods=2).var()


def TS_MAX(x, n):
    return x.rolling(_as_int(n), min_periods=1).max()


def TS_MIN(x, n):
    return x.rolling(_as_int(n), min_periods=1).min()

