@router.get("/cli-tools")

"""分钟数据清洗层（日内高频研究前置）

清洗规则（研究员视角，全部显式化，不静默丢数据）：
1. 集合竞价 bar 剔除：日首根（1m<09:31 / 5m<09:35 等）视为竞价聚合 bar，
   其成交量/成交额单独提取到 auction 信息（竞价量比因子的原料），不进主序列；
2. 半日市标记：当日 bar 数 < 常规日 80% 时标记 is_half（长假前半天、特殊休市）；
3. 一字板标记：high==low 且收盘触及涨跌停近似价 → one_line=True（封板时间因子原料）；
4. 停牌日 = 交易日历上有、但当日无任何 bar（缺失即天然不可交易，不额外标记）。

返回结构：
    panels: {field: DataFrame(index=datetime, columns=code)}（清洗后的分钟面板）
    meta:   {code: DataFrame(index=date, columns=[n_bars, is_half, one_line,
            auc_vol, auc_amt, prev_close, first_time])}（逐日摘要，因子可直接取用）
"""

from __future__ import annotations

import numpy as np
import pandas as pd

# 各周期首根有效 bar 的时刻阈值（时间字符串比较）：更早的 bar 视为竞价聚合
PERIOD_FIRST_BAR = {
    "1m": "09:31",
    "5m": "09:35",
    "15m": "09:45",
    "30m": "10:00",
    "60m": "10:30",
}
DEFAULT_FIRST_BAR = "09:35"
# 常规日完整 bar 数（A 股 4 小时连续竞价，5m=48 根；作为半日判定基准）
PERIOD_FULL_BARS = {
    "1m": 240,
    "5m": 48,
    "15m": 16,
    "30m": 8,
    "60m": 4,
}
DEFAULT_FULL_BARS = 48

# 全局缓存实例（测试可 monkeypatch 指向临时目录）
_cache = None


def _bar_time(x: pd.Timestamp) -> str:
    return f"{x.hour:02d}:{x.minute:02d}"


def clean_code_minute(
    df: pd.DataFrame,
    period: str = "5m",
    one_line: bool = True,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """清洗单只股票的分钟数据

    Args:
        df: QMT 分钟 K 线 DataFrame（index=datetime，含 open/high/low/close/volume/amount）
        period: 周期（用于首根 bar 与完整 bar 数判定）
        one_line: 是否做一字板标记（需 close/high/low）

    Returns:
        (cleaned 分钟面板, meta 逐日摘要 DataFrame)
    """
    if df is None or df.empty:
        return df, pd.DataFrame()
    d = df.copy()
    d.index = pd.to_datetime(d.index)
    d = d.sort_index()
    if "amount" not in d.columns:
        d["amount"] = d.get("volume", 0.0) * d.get("close", 0.0)

    first_bar = PERIOD_FIRST_BAR.get(period, DEFAULT_FIRST_BAR)
    full_bars = PERIOD_FULL_BARS.get(period, DEFAULT_FULL_BARS)

    t = d.index
    date_key = t.normalize()
    auc_records: dict[pd.Timestamp, dict] = {}
    # 每交易日首根（时间 < first_bar）为竞价聚合 bar：提取 auction 信息后剔除
    drop: list[bool] = []
    auc = np.zeros(len(d))
    for i in range(len(d)):
        is_first = i == 0 or date_key[i] != date_key[i - 1]
        is_auction_bar = is_first and _bar_time(t[i]) < first_bar
        drop.append(bool(is_auction_bar))
        if is_auction_bar:
            auc[i] = 1.0
            day = date_key[i]
            auc_records[day] = {
                "auc_vol": float(d["volume"].iloc[i]),
                "auc_amt": float(d["amount"].iloc[i]),
                "auc_time": _bar_time(t[i]),
            }
    d = d[~np.array(drop)]

    if d.empty:
        return d, pd.DataFrame()

    # 逐日摘要
    t2 = d.index
    date_key2 = t2.normalize()
    days: list[dict] = []
    for day, g in d.groupby(date_key2):
        rec = {
            "n_bars": len(g),
            "is_half": len(g) < int(full_bars * 0.8),
            "one_line": False,
        }
        auc_info = auc_records.get(day, {})
        rec.update(auc_info)
        if one_line and {"high", "low", "close"} <= set(g.columns):
            # 全日所有 bar high==low（无波动区间）且收盘钉在限价位 → 一字板
            rec["one_line"] = bool(
                (g["high"] - g["low"]).abs().max() < 1e-9
            )
        rec["prev_close"] = None
        days.append((day, rec))
    meta = pd.DataFrame([r for _, r in days], index=[k for k, _ in days])
    meta.index.name = "date"

    # prev_close：上一交易日收盘价（跨日连续，用于隔夜收益）
    if "close" in d.columns:
        closes = d["close"]
        prev = pd.Series(
            closes.groupby(date_key2).last().shift(1), index=meta.index
        )
        meta["prev_close"] = prev.to_numpy()
    return d, meta


def load_intraday_panels(
    codes: list[str],
    period: str = "5m",
    start_date: str = "",
    end_date: str = "",
    clean: bool = True,
) -> dict:
    """加载多只股票的分钟面板（清洗后）

    Args:
        codes: 股票代码；空则取本地全部该周期缓存
        period: 分钟周期（1m/5m/15m/30m/60m）
        clean: 是否做清洗（竞价剔除/半日/一字标记）；False 返回原始分钟面板

    Returns:
        {
          "panels": {field: DataFrame(index=datetime, columns=code)},
          "meta": {code: DataFrame(index=date, ...)},
          "codes": [...], "period": period,
          "start": "YYYY-MM-DD", "end": "YYYY-MM-DD",
          "cleaned": bool,
          "missing": [code...]
        }
    """
    from backend.config import settings
    from backend.data.cache import DataCache

    cache = _cache if _cache is not None else DataCache(settings.cache_dir)
    if not codes:
        codes = list_cached_codes(period)
    if not codes:
        raise ValueError(
            f"本地无 {period} 分钟缓存 — 请先在「数据管理」下载分钟行情"
            "（周期需与请求一致），或指定股票池"
        )

    fields = ["open", "high", "low", "close", "volume", "amount"]
    series_map: dict[str, dict] = {f: {} for f in fields}
    meta_map: dict[str, pd.DataFrame] = {}
    missing: list[str] = []
    for code in codes:
        df = cache.get(code, period)
        if df is None or df.empty:
            missing.append(code)
            continue
        if clean:
            df, meta = clean_code_minute(df, period)
            if df.empty:
                missing.append(code)
                continue
            if not meta.empty:
                meta_map[code] = meta
        df = df.copy()
        df.index = pd.to_datetime(df.index)
        df = df.sort_index()
        if start_date:
            df = df[df.index >= pd.Timestamp(start_date)]
        if end_date:
            df = df[df.index <= pd.Timestamp(end_date) + pd.Timedelta(days=1)]
        for f in fields:
            if f in df.columns:
                series_map[f][code] = df[f].astype(float)

    if not series_map["close"]:
        raise ValueError(
            f"未找到任何 {period} 分钟数据 — 请先下载分钟行情（可先在小股票池验证）"
        )
    panels = {
        f: pd.DataFrame(m).sort_index() for f, m in series_map.items() if m
    }
    first = panels["close"].index[0]
    last = panels["close"].index[-1]
    return {
        "panels": panels,
        "meta": meta_map,
        "codes": list(panels["close"].columns),

        "period": period,
        "start": str(first.date()),
        "end": str(last.date()),
        "cleaned": clean,
        "missing": missing,
        "n_bars_per_stock": {c: int(panels["close"].shape[0]) for c in panels["close"].columns},
    }


def list_cached_codes(period: str = "5m") -> list[str]:
    """本地指定周期缓存股票列表"""
    from backend.services import market_data

    return market_data.list_cached_codes(period)
"""日内高频聚合算子库 — 分钟面板 → 日频因子面板

设计语义（与 docs 分钟级设计一致）：
- 分钟级字段 m_open/m_high/m_low/m_close/m_volume/m_amount：
  DataFrame(index=datetime, columns=code)；
- ID_* 聚合算子把分钟维度按自然日折叠成 DataFrame(index=date, columns=code)，
  输出与现有日频因子面板同构，下游 IC/分层/回测全链路直接复用；
- M_* 序列算子作用于分钟维度（按日分组滚动，不跨日混算）；
- 现成高频因子函数（TAIL_RET/RV/JUMP_DAY/...）无参调用，闭包内取面板。

清洗约定：调用方先过 intraday_cleaner（竞价 bar 已剔除，meta 含一字/半日标记）。
"""

from __future__ import annotations

import numpy as np
import pandas as pd

# ── 工具 ─────────────────────────────────────────────────────────


def _date_key(idx: pd.DatetimeIndex) -> pd.Index:
    """datetime index → 自然日 index（同长度，用于 groupby）"""
    return pd.DatetimeIndex(idx.normalize().unique())


def _intraday_pct_change(panel: pd.DataFrame) -> pd.DataFrame:
    """日内收益：逐日 pct_change，**日首根置 NaN**（隔夜跳空不属于日内波动）"""
    rets = panel.pct_change()
    norm = np.asarray(pd.DatetimeIndex(panel.index).normalize())
    is_new_day = np.concatenate([[True], norm[1:] != norm[:-1]])
    rets.loc[is_new_day] = np.nan
    return rets


def _collapse(series: pd.DataFrame, agg) -> pd.DataFrame:
    """分钟面板 (dt × code) → 日频面板 (date × code)：按列分组到自然日聚合"""
    out: dict[str, pd.Series] = {}
    for code in series.columns:
        s = series[code].dropna()
        if s.empty:
            continue
        out[code] = s.groupby(s.index.normalize()).agg(agg)
    if not out:
        return pd.DataFrame()
    return pd.DataFrame(out).sort_index()


def _within_time(series: pd.DataFrame, start: str, end: str) -> pd.DataFrame:
    """时段切片：保留时刻在 [start, end) 内的分钟 bar（start/end 如 '09:30'）"""
    times = series.index.strftime("%H:%M")
    mask = (times >= start) & (times < end)
    return series.loc[mask]


# ── ID_* 聚合算子（分钟 → 日） ─────────────────────────────────────


def ID_LAST(series: pd.DataFrame, n_bars: int = 0) -> pd.DataFrame:
    """每日最后一根 bar 的值；n_bars>0 时为最后 n 根均值（更稳健的收盘估计）"""
    if n_bars and n_bars > 0:
        out = {}
        for code in series.columns:
            s = series[code].dropna()
            if s.empty:
                continue
            t = s.groupby(s.index.normalize()).tail(n_bars)
            out[code] = t.groupby(t.index.normalize()).mean()
        return pd.DataFrame(out).sort_index()
    return _collapse(series, "last")


def ID_FIRST(series: pd.DataFrame, n_bars: int = 0) -> pd.DataFrame:
    """每日第一根 bar 的值；n_bars>0 时为前 n 根均值"""
    if n_bars and n_bars > 0:
        out = {}
        for code in series.columns:
            s = series[code].dropna()
            if s.empty:
                continue
            t = s.groupby(s.index.normalize()).head(n_bars)
            out[code] = t.groupby(t.index.normalize()).mean()
        return pd.DataFrame(out).sort_index()
    return _collapse(series, "first")


def ID_SUM(series: pd.DataFrame) -> pd.DataFrame:
    return _collapse(series, "sum")


def ID_MEAN(series: pd.DataFrame) -> pd.DataFrame:
    return _collapse(series, "mean")


def ID_MAX(series: pd.DataFrame) -> pd.DataFrame:
    return _collapse(series, "max")


def ID_MIN(series: pd.DataFrame) -> pd.DataFrame:
    return _collapse(series, "min")


def ID_STD(series: pd.DataFrame) -> pd.DataFrame:
    return _collapse(series, "std")


def ID_MEDIAN(series: pd.DataFrame) -> pd.DataFrame:
    return _collapse(series, "median")


def ID_QUANTILE(series: pd.DataFrame, q: float = 0.5) -> pd.DataFrame:
    out = {}
    for code in series.columns:
        s = series[code].dropna()
        if s.empty:
            continue
        out[code] = s.groupby(s.index.normalize()).quantile(q)
    return pd.DataFrame(out).sort_index()


def ID_COUNT(series: pd.DataFrame) -> pd.DataFrame:
    return _collapse(series, "count")


def ID_SLICE(series: pd.DataFrame, start: str, end: str) -> pd.DataFrame:
    """时段切片（返回分钟级）：ID_SLICE(m_close, '14:00', '15:00') 后再套 ID_*"""
    return _within_time(series, start, end)


# ── M_* 序列算子（分钟维度，按日分组不跨日） ────────────────────────


def _apply_daily_rolling(series: pd.DataFrame, window: int, func) -> pd.DataFrame:
    out: dict[str, pd.Series] = {}
    for code in series.columns:
        s = series[code].dropna()
        if s.empty:
            continue
        g = s.groupby(s.index.normalize()).rolling(window, min_periods=1).apply(
            func, raw=False
        )
        g = g.droplevel(0)
        out[code] = g
    return pd.DataFrame(out).sort_index()


def M_DELAY(series: pd.DataFrame, n: int = 1) -> pd.DataFrame:
    """分钟维度前 n 根（按日分组，日首根为 NaN）"""
    out = {}
    for code in series.columns:
        s = series[code]
        g = s.groupby(s.index.normalize()).shift(n)
        out[code] = g
    return pd.DataFrame(out).sort_index()


def M_MA(series: pd.DataFrame, n: int = 12) -> pd.DataFrame:
    return _apply_daily_rolling(series, n, lambda x: x.mean())


def M_SUM(series: pd.DataFrame, n: int = 12) -> pd.DataFrame:
    return _apply_daily_rolling(series, n, lambda x: x.sum())


def M_STD(series: pd.DataFrame, n: int = 12) -> pd.DataFrame:
    return _apply_daily_rolling(series, n, lambda x: x.std())


def M_CUMSUM(series: pd.DataFrame) -> pd.DataFrame:
    out = {}
    for code in series.columns:
        s = series[code]
        out[code] = s.groupby(s.index.normalize()).cumsum()
    return pd.DataFrame(out).sort_index()


# ── 现成高频因子（无参，闭包取面板；返回日频面板） ──────────────────


def TAIL_RET(panels: dict, n_bars: int = 12) -> pd.DataFrame:
    """尾盘动量：当日最后 n 根 bar 的累计收益 close[-1] / close[-1-n] - 1"""
    close = panels["close"]
    close_last = ID_LAST(close, 0)
    close_minus_n = ID_LAST(M_DELAY(close, n_bars), 0)  # 第 (-1-n) 根 bar 收盘
    return close_last / close_minus_n - 1.0


def OPEN_RET(panels: dict, n_bars: int = 6) -> pd.DataFrame:
    """开盘反转：当日前 n 根 bar 的累计收益 close[n-1] / 昨收 - 1"""
    close = panels["close"]
    prev_close = ID_LAST(close, 0).shift(1)
    close_n = ID_FIRST(M_DELAY(close, -(n_bars - 1)), 0)  # 第 n 根 bar 收盘
    return close_n / prev_close - 1.0


def RV(panels: dict, n_bars: int = 48) -> pd.DataFrame:
    """已实现波动率：日内分钟收益平方和（日频）；n_bars=48 对应全日 5m

    日内收益逐日计算并屏蔽日首根（隔夜跳空不计入日内波动）。
    """
    close = panels["close"]
    rets = _intraday_pct_change(close)
    return ID_SUM(rets**2)


def JUMP_DAY(panels: dict) -> pd.DataFrame:
    """跳跃占比：RV / BV（双幂变差）；>1 表示当日存在跳跃性波动"""
    close = panels["close"]
    rets = _intraday_pct_change(close)
    rv = ID_SUM(rets**2)
    r1 = M_DELAY(rets, 1)
    bv = ID_SUM(rets.abs() * r1.abs()) * (np.pi / 2)
    return rv.div(bv.replace(0, np.nan))


def AMIHUD5(panels: dict) -> pd.DataFrame:
    """日内非流动性：每根 bar |收益|/成交额 的日均值 × 1e9（Amihud 分钟口径）"""
    close = panels["close"]
    amount = panels.get("amount")
    if amount is None:
        return pd.DataFrame()
    rets = _intraday_pct_change(close).abs()
    illiq = rets.div(amount.replace(0, np.nan))
    return ID_MEAN(illiq) * 1e9


def VWAP_DEV(panels: dict) -> pd.DataFrame:
    """价格偏离日内 VWAP：收盘 / 全日 VWAP - 1（尾盘拉抬/砸盘信号）"""
    close = panels["close"]
    amount = panels.get("amount")
    volume = panels.get("volume")
    if amount is None or volume is None:
        return pd.DataFrame()
    day_vwap = ID_SUM(amount) / ID_SUM(volume).replace(0, np.nan)
    return ID_LAST(close, 0).div(day_vwap.replace(0, np.nan)) - 1.0


def VOLUME_CLOCK(panels: dict) -> pd.DataFrame:
    """成交量时钟（日内量能集中度）：Σ(份额²)，1/n 为均匀分布，越接近 1 越集中"""
    volume = panels.get("volume")

